{"version":3,"sources":["../scss/_storesListItem.scss","stores.css","../scss/_mixins.scss","../scss/_variables.scss","../scss/stores.scss"],"names":[],"mappings":"AAAA;EACE,aAAA;EACA,SAAA;EACA,oBAAA;EACA,gCAAA;ACCF;;ADEA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACCF;;ADEA;EACE,eAAA;EACA,cAAA;ACCF;ADAE;EACE,iBAAA;EACA,WAAA;EACA,YAAA;EACA,sBAAA;KAAA,mBAAA;EACA,0BAAA;KAAA,uBAAA;ACEJ;;ADEA;EACE,eAAA;ACCF;ADAE;EE1BE,uCAAA;EACA,gBF0BiC;EEzBjC,kBAAA;EACA,cCJQ;EDKR,eFuB2B;ACM/B;ADJI;EACE,UG7BO;AFmCb;ADHE;EEjCE,uCAAA;EACA,gBFiCoC;EEhCpC,kBAAA;EACA,YCHW;EDIX,eF8B8B;ACSlC;;ADLA;EACE,yBAAA;ACQF;;ADLA;EE1CI,uCAAA;EACA,gBF0C4B;EEzC5B,kBAAA;EACA,cFwCa;EEvCb,eFuCsB;ACY1B;;AGpDA;EACE,gBAAA;EACA,oBAAA;EACA,gCAAA;AHuDF;;AGpDA;EFTI,uCAAA;EACA,gBESkC;EFRlC,kBAAA;EACA,YCHW;EDIX,eEM4B;EAC9B,mBAAA;AH2DF;;AGxDA;EACE,aAAA;EACA,4DAAA;AH2DF;AGzDE;EFlBE,uCAAA;EACA,gBEkBiC;EFjBjC,kBAAA;EACA,cCJQ;EDKR,eEe2B;AH+D/B;AG7DI;EACE,UDrBO;AFoFb;;AG1DA;EACE,gBAAA;AH6DF;;AG3DA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;AH8DF","file":"stores.css","sourcesContent":[".stores__list-item {\n  display: flex;\n  gap: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid $gray;\n}\n\n.stores__list-item-about {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.stores__list-item-img {\n  flex: 0 0 160px;\n  display: block;\n  & img {\n    max-height: 120px;\n    width: 100%;\n    height: 100%;\n    object-fit: contain;\n    object-position: center;\n  }\n}\n\n.stores__list-item-about {\n  flex: 0 1 300px;\n  & a {\n    @include fonts($mainColor, 18px, 600);\n\n    &:hover {\n      color: $colorHover;\n    }\n  }\n  & p {\n    @include fonts($defaultColor, 14px, 400);\n  }\n}\n\n.stores__list-item-district {\n  color: #545454 !important;\n}\n\n.stores__list-item-category {\n  @include fonts(#545454, 14px, 400);\n}\n",".stores__list-item {\n  display: flex;\n  gap: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.stores__list-item-about {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.stores__list-item-img {\n  flex: 0 0 160px;\n  display: block;\n}\n.stores__list-item-img img {\n  max-height: 120px;\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  object-position: center;\n}\n\n.stores__list-item-about {\n  flex: 0 1 300px;\n}\n.stores__list-item-about a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 18px;\n}\n.stores__list-item-about a:hover {\n  color: red;\n}\n.stores__list-item-about p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n.stores__list-item-district {\n  color: #545454 !important;\n}\n\n.stores__list-item-category {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #545454;\n  font-size: 14px;\n}\n\n.category_navigation_bar {\n  margin-top: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.number_of_advertisements {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  margin: 10px 0 20px;\n}\n\n.category_list {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\n}\n.category_list a {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #3077a0;\n  font-size: 14px;\n}\n.category_list a:hover {\n  color: red;\n}\n\n.stores {\n  margin-top: 20px;\n}\n\n.stores__list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);","@import \"./variables\";\n@import \"./mixins\";\n@import \"./storesListItem\";\n\n.category_navigation_bar {\n  margin-top: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid $gray;\n}\n\n.number_of_advertisements {\n  @include fonts($defaultColor, 14px, 400);\n  margin: 10px 0 20px;\n}\n\n.category_list {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));\n\n  & a {\n    @include fonts($mainColor, 14px, 400);\n\n    &:hover {\n      color: $colorHover;\n    }\n  }\n}\n\n.stores {\n  margin-top: 20px;\n}\n.stores__list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}"]}flex;\n  flex-direction: column;\n  gap: 10px;\n}"]}